scripts.count_inversions:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']

    # Count inversions: pairs (i,j) where i < j but values[i] > values[j]
    inversions = 0
    n = len(values)

    for i in range(n):
        for j in range(i + 1, n):
            if values[i] > values[j]:
                inversions += 1

    return float(inversions)

scripts.factorial_mod:
def solve(inputs: dict) -> float:
    n = int(inputs['N'])
    mod = int(inputs['MOD'])

    # Calculate n! mod mod
    result = 1
    for i in range(1, n + 1):
        result = (result * i) % mod

    return float(result)

scripts.lcg_generator:
def solve(inputs: dict) -> float:
    x = int(inputs['SEED'])
    a = int(inputs['A'])
    b = int(inputs['B'])
    m = int(inputs['M'])
    k = int(inputs['K'])

    # Apply the LCG formula k times
    for _ in range(k):
        x = (a * x + b) % m

    return float(x)

scripts.sum_floor_division:
def solve(inputs: dict) -> float:
    a = inputs['A']
    b = inputs['B']

    # Sum of floor divisions
    total = 0
    for i in range(len(a)):
        total += a[i] // b[i]

    return float(total)

